    report: BackupReport,
    webhook_url: str,
) -> None:
    """Send a backup report via a Slack incoming webhook."""
    payload = {
        "text": _build_subject(report),
        "blocks": [
            {
                "type": "section",
                "text": {
                    "type": "mrkdwn",
                    "text": _build_slack_body(report),
