    """Build the plain-text email body."""
    lines: list[str] = [_build_subject(report), ""]

    for result in report.results:
        status = "OK" if result.success else "FAILED"
        lines.append(
            f"  [{status}] {result.server.driver}://"
            f"{result.server.host}/{result.database}"
