            key = format_s3_key(
                args.s3_key, config, dbname, now, dest,
            )
            s3_uri = upload_to_s3(
                dest,
                args.s3_bucket,
                key,
                endpoint_url=getattr(
                    args, "s3_endpoint_url", None
                ),
            )
        except Exception as exc:
            logger.error("Failed to upload to S3: %s", exc)
