        lines.append(
            f"{emoji} `{result.server.driver}://"
            f"{result.server.host}/{result.database}`"
        )
        if result.success:
            lines.append(f"  Local: `{result.local_path}`")
            lines.append(
                f"  Size: {_format_size(result.size)}"
            )
            if result.s3_uri:
                lines.append(f"  S3: `{result.s3_uri}`")
        else:
            lines.append(f"  Error: {result.error}")

    lines.append("")
